function splitList(value) {
  if (!value || value === 'N/A') return [];
  return [...new Set(value.split(',').map(s => s.trim()).filter(Boolean))];
}

function numberOrNull(value) {
  if (!value || value === 'N/A') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

return $input.all().map(item => {
  const movie = item.json;

  if (movie.Response !== 'True' || !movie.imdbID) {
    throw new Error(movie.Error || 'Invalid OMDb movie response');
  }

  if (!movie.Plot || movie.Plot === 'N/A') {
    throw new Error(`Missing plot for ${movie.imdbID}`);
  }

  return {
    json: {
      imdbId: movie.imdbID,
      title: movie.Title,
      year: numberOrNull(movie.Year),
      runtimeMinutes: numberOrNull(
        movie.Runtime?.replace(/\s*min$/, '')
      ),
      imdbRating: numberOrNull(movie.imdbRating),
      plot: movie.Plot,
      directors: splitList(movie.Director),
      actors: splitList(movie.Actors),
      genres: splitList(movie.Genre),
      source: `https://www.imdb.com/title/${movie.imdbID}/`,
      dataSource: 'OMDb',
      embeddingText: [
        `Title: ${movie.Title}`,
        `Genres: ${movie.Genre}`,
        `Plot: ${movie.Plot}`
      ].join('\n')
    }
  };
});

